import{_ as s,o as l,a as e,b as t}from"./app.C41L12d5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"原子操作","link":"/api/SIMT-API/atomic_operations/atomic_operations"},{"text":"原子操作简介","link":"/api/SIMT-API/atomic_operations/atomic_operations_intro"}]},"headers":[],"relativePath":"api/SIMT-API/atomic_operations/atomic_operations_intro.md","filePath":"api/SIMT-API/atomic_operations/atomic_operations_intro.md","outlineHeaders":[{"level":2,"title":"访问空间","slug":"访问空间","link":"#访问空间"},{"level":2,"title":"原子操作机制","slug":"原子操作机制","link":"#原子操作机制"},{"level":3,"title":"基本执行过程","slug":"基本执行过程","link":"#基本执行过程"},{"level":3,"title":"Global Memory原子操作原理","slug":"Global-Memory原子操作原理","link":"#Global-Memory原子操作原理"},{"level":3,"title":"UB原子操作原理","slug":"UB原子操作原理","link":"#UB原子操作原理"},{"level":2,"title":"确定性","slug":"确定性","link":"#确定性"},{"level":2,"title":"性能影响","slug":"性能影响","link":"#性能影响"},{"level":3,"title":"Global Memory原子操作","slug":"Global-Memory原子操作","link":"#Global-Memory原子操作"},{"level":3,"title":"UB原子操作","slug":"UB原子操作","link":"#UB原子操作"},{"level":2,"title":"使用建议","slug":"使用建议","link":"#使用建议"}],"lastUpdated":1787050286000}'),o={name:"api/SIMT-API/atomic_operations/atomic_operations_intro.md"};function p(n,a,i,c,r,h){return l(),e("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>原子操作简介</h1><p>SIMT原子操作用于保证对同一地址的一次读-改-写过程具有原子性，可避免多个线程并发更新同一地址时出现更新丢失。原子操作常用于计数、状态抢占、直方图统计、归约计算和共享状态位更新等场景。</p><p>原子操作保证单次内存更新不可被其他线程打断，但不保证多个线程到达该原子操作的先后顺序，也不能替代线程同步屏障功能。</p><h2 id="访问空间">访问空间<a class="header-anchor" href="#访问空间">​</a></h2><p>原子操作可以作用于Global Memory或Unified Buffer（UB）。不同内存空间的作用范围、适用场景和性能特征不同。</p><table><thead><tr><th>访问空间</th><th>作用范围</th><th>典型用途</th><th>性能特征</th></tr></thead><tbody><tr><td>Global Memory</td><td>Grid内线程可访问</td><td>全局计数、跨线程块汇总、最终结果写回</td><td>访问路径较长，跨线程块或跨核竞争同一地址时开销较高</td></tr><tr><td>UB</td><td>线程块内线程可访问</td><td>局部统计、块内归约、临时直方图</td><td>位于片上内存，访问延迟通常低于Global Memory，但作用范围仅限当前线程块</td></tr></tbody></table><p>不同接口、不同数据类型支持的内存空间存在差异，具体请参见各接口文档中的“不同数据类型支持的内存范围”。</p><h2 id="原子操作机制">原子操作机制<a class="header-anchor" href="#原子操作机制">​</a></h2><p>本节所述机制适用于本章列出的所有SIMT原子操作。不同接口执行的判定或计算不同，但保证原子性的基本过程相同。</p><h3 id="基本执行过程">基本执行过程<a class="header-anchor" href="#基本执行过程">​</a></h3><p>一次原子操作包含以下步骤：</p><ol><li>从目标地址读取旧值。</li><li>按照接口语义执行判定或计算。例如，算术类接口执行加、减、取最大值或取最小值；交换类接口确定待写入值；比较交换接口先比较旧值，再决定是否写入新值；按位类接口执行相应的按位计算。</li><li>按照接口语义写回结果。</li></ol><p>硬件将上述步骤作为一个不可分割的整体执行。在当前原子操作完成前，其他线程对同一地址发起的原子操作不能修改该地址。因此，多个线程对同一地址执行原子操作时，请求只能依次执行，不能并行完成。原子操作可以保证单次读-改-写过程不受其他线程干扰，但不保证各线程请求的执行顺序。</p><h3 id="Global-Memory原子操作原理">Global Memory原子操作原理<a class="header-anchor" href="#Global-Memory原子操作原理">​</a></h3><p>Global Memory（GM）位于AI Core外部，是Grid内所有线程均可访问的设备端内存。L2 Cache是核外共享缓存，用于缓存GM中的数据，减少对GM的直接访问。L2 Cache保存的数据来自GM：访问命中时可直接使用L2 Cache中的数据，未命中时需要从GM加载对应数据。L2 Cache与GM之间的数据一致性由硬件保证。</p><p>Cache Line（缓存行）是Cache加载、标记、替换和写回数据的最小管理粒度。Cache不会只缓存一个变量或一个数据地址，而是将目标地址所在的一段连续GM数据加载到L2 Cache中，这段数据在L2 Cache中的缓存副本称为一条Cache Line。对于本文所述的GM原子操作处理路径，Cache Line大小为512B，Cache Line中又包含四个128B的Sector，GM原子操作以128B地址范围为粒度。</p><p>多个原子操作的目标地址集中在同一个128B地址范围内时，访问竞争较强，吞吐较低；目标地址分散在更多128B地址范围内时，访问竞争减弱，吞吐较高。因此，评估GM原子操作性能时，需要关注目标地址在128B地址范围内的分布。</p><p>数据宽度会影响一个128B地址范围能够容纳的连续目标地址数量：</p><table><thead><tr><th>数据宽度</th><th>单个地址占用空间</th><th>每个128B地址范围容纳的连续地址数</th></tr></thead><tbody><tr><td>32位</td><td>4B</td><td>32</td></tr><tr><td>64位</td><td>8B</td><td>16</td></tr></tbody></table><p>例如，32个连续的32位地址位于1个128B地址范围内，而32个连续的64位地址分布在2个128B地址范围内。在原子操作数量和地址数量相同的情况下，后者的目标地址分布范围更多，访问竞争相对较弱，性能通常更高。但这不表示64位原子操作一定快于32位原子操作：如果所有线程访问同一地址，无论数据宽度如何，目标地址都会集中在同一个128B地址范围内；如果地址分布、操作类型或返回值使用方式不同，性能结果也会随之变化。因此，评估GM原子操作性能时，应同时考虑同一地址的竞争线程数、目标地址在128B地址范围内的分布，以及具体接口的执行开销。</p><h3 id="UB原子操作原理">UB原子操作原理<a class="header-anchor" href="#UB原子操作原理">​</a></h3><p>多个线程在UB上执行原子操作时，请求按照上文所述的基本执行过程串行执行，不受bank冲突的影响。</p><h2 id="确定性">确定性<a class="header-anchor" href="#确定性">​</a></h2><p>原子操作可以避免数据竞争造成的更新丢失，但不一定保证结果在所有场景下完全确定。</p><p>对于整数计数类操作，如果不发生溢出，最终计数值通常是确定的。例如所有线程执行<code>asc_atomic_add(counter, 1U)</code>接口，最终结果等于参与累加的线程数量。</p><p>对于依赖原子操作返回值的场景，输出顺序通常不确定。例如以下写法可以获得唯一写入位置，但不同线程获得的位置顺序可能随调度变化：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">pos</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="n">count</span><span class="p">,</span><span class="w"> </span><span class="mi">1U</span><span class="p">);</span>
<span class="n">out</span><span class="p">[</span><span class="n">pos</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">value</span><span class="p">;</span>
</code></pre></div><p>对于抢占类场景，例如使用<code>asc_atomic_cas</code>接口将某个状态从0改为线程ID，原子操作可以保证最多一个线程抢占成功，但无法保证固定由哪个线程抢占成功。</p><p>对于浮点累加类场景，由于浮点加法不满足严格结合律，不同线程的更新顺序可能导致低位舍入差异。如果业务要求逐bit一致，应避免将大量浮点数据直接原子累加到同一个Global Memory地址，可改用固定顺序的分层归约。</p><h2 id="性能影响">性能影响<a class="header-anchor" href="#性能影响">​</a></h2><p>原子操作的性能主要受访问空间、同一地址的竞争程度、目标地址在128B地址范围内的分布和返回值依赖影响。</p><h3 id="Global-Memory原子操作">Global Memory原子操作<a class="header-anchor" href="#Global-Memory原子操作">​</a></h3><p>Global Memory原子操作适合做最终结果汇总，但不适合高频热点更新。多个线程块或多个核同时访问同一Global Memory地址时，访问竞争较强，吞吐会明显下降。具体性能特征请参见<a href="#global-memory%E5%8E%9F%E5%AD%90%E6%93%8D%E4%BD%9C%E5%8E%9F%E7%90%86">Global Memory原子操作原理</a>。</p><p>例如所有线程都访问同一个<code>counter</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_atomic_add</span><span class="p">(</span><span class="n">counter</span><span class="p">,</span><span class="w"> </span><span class="mi">1U</span><span class="p">);</span>
</code></pre></div><p>该地址会成为热点，原子操作吞吐会明显下降。即使不同线程访问不同地址，也应避免这些地址过度集中在少量128B地址范围内。</p><h3 id="UB原子操作">UB原子操作<a class="header-anchor" href="#UB原子操作">​</a></h3><p>UB原子操作适合线程块内局部聚合。相比直接写Global Memory，它可以减少全局内存访问和跨线程块竞争。但UB的作用范围有限，不能直接替代跨线程块共享的Global Memory结果。</p><p>常见优化方式如下：</p><ol><li>每个线程先在寄存器中计算局部结果。</li><li>线程块内使用UB进行局部累加或归约。</li><li>每个线程块只对Global Memory执行少量原子操作。</li></ol><h2 id="使用建议">使用建议<a class="header-anchor" href="#使用建议">​</a></h2><ul><li>仅在确实存在并发写同一地址且需要保证更新不丢失时使用原子操作。</li><li>避免所有线程频繁原子更新同一个Global Memory地址。</li><li>优先采用寄存器或UB进行局部聚合，再写回Global Memory。</li><li>不要依赖原子操作返回值表达稳定的线程执行顺序。</li><li>浮点累加要求逐bit一致时，应使用固定顺序归约，避免直接高并发原子累加。</li><li>使用<code>asc_atomic_cas</code>实现抢占逻辑时，应保证业务只要求“有一个线程成功”，而不是要求固定线程成功。</li></ul></article></div>`,1)])])}const b=s(o,[["render",p]]);export{m as __pageData,b as default};
